"""Code-pinned optimistic unread UI bridge. Reads no credentials or messages."""
from __future__ import annotations
import copy
import hashlib
from pathlib import Path
import pefile
from build_mod import payload_file

PIN = {'schema': 1, 'readRva': 32428864, 'decrementRva': 32428988, 'incomingRva': 32430240, 'staleRva': 32430481, 'countRva': 32430807, 'destructorRva': 32413664, 'chatDeleteRva': 32427296, 'vtableRva': 65994744, 'guards': [{'rva': 32428864, 'expected': ''}, {'rva': 32430240, 'expected': ''}, {'rva': 32413664, 'expected': '48895c2408574883ec208bda488bf9e806cb14fef6c301740dba78010000488bcfe8f40219fe488b5c2430488bc74883c4205fc3'}, {'rva': 32427296, 'expected': ''}, {'rva': 449281, 'expected': 'e9dabce701'}, {'rva': 595616, 'expected': 'e99bbce501'}], 'destructorThunkRva': 449281, 'readThunkRva': 595616, 'missingRva': 32430298, 'selfInfo': {'readerVtableRva': 26219000, 'readerSlot': 16, 'readerThunkRva': 68946, 'modelOffset': 16, 'modelVtableRva': 25914384, 'modelSlot': 24, 'modelThunkRva': 261261, 'getterRva': 17654624, 'guards': [{'rva': 68946, 'expected': 'e909560c01'}, {'rva': 17654624, 'expected': '40534883ec20488b4910488bda488b01ff5018488bc34883c4205bc3'}, {'rva': 261261, 'expected': 'e92e436e00'}, {'rva': 7487424, 'expected': '40535556574883ec28488d6928488bf9488bcd488bf2e86a9899ff488b47384885c07404f0ff4008488b5f30488bcd488b7f38e8a42295ff488b034889064885ff742cbbffffffff8bc3f00fc1470883f801751b488b07488bcfff10f00fc15f0c83fb017509488b07488bcfff5008488bc64883c4285f5e5d5bc3'}]}}

def specification(root: Path) -> dict:
    path = payload_file(root, "max.exe")
    return specification_from_bytes(path.read_bytes(), module_path=path)

def specification_from_bytes(data: bytes, *, module_path: Path) -> dict:
    if type(data) is not bytes:
        raise ValueError("Unsupported ghost UI image")
    try:
        pe = pefile.PE(data=data, fast_load=True)
        if (pe.FILE_HEADER.Machine != 0x8664 or pe.OPTIONAL_HEADER.Magic != 0x20b
                or pe.OPTIONAL_HEADER.SizeOfImage <= PIN["vtableRva"] + 16):
            raise ValueError("Unsupported ghost UI image")
        for guard in PIN["guards"]:
            expected = bytes.fromhex(guard["expected"])
            if pe.get_data(guard["rva"], len(expected)) != expected:
                raise ValueError("Unsupported ghost UI code")
        for slot, name, body in ((0, "destructorThunkRva", "destructorRva"),
                                 (8, "readThunkRva", "readRva")):
            target = pe.OPTIONAL_HEADER.ImageBase + PIN[name]
            if pe.get_data(PIN["vtableRva"] + slot, 8) != target.to_bytes(8, "little"):
                raise ValueError("Unsupported ghost UI virtual entry")
            code = pe.get_data(PIN[name], 5)
            if code[:1] != b'\xe9' or PIN[name] + 5 + int.from_bytes(code[1:], "little", signed=True) != PIN[body]:
                raise ValueError("Unsupported ghost UI jump thunk")
    except (pefile.PEFormatError, IndexError, TypeError, ValueError) as error:
        raise ValueError("Unsupported ghost UI image") from error
    return {**copy.deepcopy(PIN), "modulePath": str(module_path),
            "moduleSha256": hashlib.sha256(data).hexdigest(), "moduleSize": len(data),
            "imageSize": pe.OPTIONAL_HEADER.SizeOfImage}
